(async () => {
    const m = window.__mymechanics; const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
    await m.actions.ensureKernel();
    if (m.state.editing) m.actions.cancelEditing({ quiet: true });
    await m.actions.closeProject({ force: true });
    await m.actions.newDocument('part');
    const F = await import('/src/cad/features.js'); const S = await import('/src/cad/sketch.js');
    const part = m.active();
    const top = { kind: 'std', name: 'top' };
    const sk = (plane, draw) => { const s = F.createFeature(part, 'sketch', { plane, ...S.createSketchGeometry() }); draw(s, S); return s; };
    const base = sk(top, (s) => S.addRectangle(s, 0, 0, 60, 40));
    const below = F.createFeature(part, 'plane', { base: top, offset: -30 });
    const above = F.createFeature(part, 'plane', { base: top, offset: 70 });
    m.actions.change('op.addFeature', () => { part.features.push(base, F.createFeature(part, 'extrude', { sketch: base.id, depth: 20 }), below, above); });
    window.__xm = {
      sleep,
      vol: async () => { const { rep } = await import('/src/cad/kernel.js'); return rep().measureVolume(m.actions.buildPart(m.active()).body); },
      addSketch: (plane, draw) => { const s = sk(plane, draw); m.actions.change('op.addFeature', () => { m.active().features.push(s); }); return s; },
      ref: (f) => ({ kind: 'ref', id: f.id }),
      below, above,
      extrudeOf: async (s) => { m.state.selection = [{ kind: 'feat', id: s.id, key: `feat:${s.id}` }]; await m.run('extrude'); await sleep(400); },
      choose: async (key, value) => { const el = document.querySelector(`#left-panel [data-pm-select="${key}"]`); el.value = value; el.dispatchEvent(new Event('change', { bubbles: true })); await sleep(400); },
      tick: async (key) => { document.querySelector(`#left-panel [data-pm-toggle="${key}"]`).click(); await sleep(400); },
      pickBox: async (key) => { document.querySelector(`#left-panel [data-pm-pick="${key}"]`).click(); await sleep(150); },
      // A click on a face of the part in the graphics area (the viewport's pick callback, as a real click gives it).
      pickFace: async (test, point) => {
        const faces = m.state.partEntry.faces; const index = faces.findIndex(test);
        m.viewport.options.onPick({ kind: 'face', bodyKey: 'body', index, point: point ?? [faces[index].center.x, faces[index].center.y, faces[index].center.z] }, { clientX: 0, clientY: 0 });
        await sleep(500);
      },
    };
    await sleep(300);
    return String(Math.round(await window.__xm.vol()));
  })()

(async () => {
    const m = window.__mymechanics; const X = window.__xm;
    const s = X.addSketch(X.ref(X.below), (k, S) => S.addCircle(k, 30, 20, 5));
    await X.extrudeOf(s);
    await X.choose('end', 'upToSurface');
    await X.pickBox('endFace');
    await X.pickFace((f) => f.geomType === 'PLANE' && Math.abs(f.center.z - 20) < 1e-6);
    const items = document.querySelectorAll('#left-panel [data-pm-pick="endFace"] li').length;
    const err = document.querySelector('#left-panel .pm-error')?.textContent ?? '';
    m.actions.acceptEditing(); await X.sleep(500);
    const v = await X.vol();
    return `${items} ${err ? 'error' : 'ok'} ${Math.abs(v - (48000 + Math.PI * 25 * 30)) < 1e-3}`;
  })()

(async () => {
    const m = window.__mymechanics; const X = window.__xm;
    const f = m.active().features.at(-1);
    await m.actions.editFeature(f.id); await X.sleep(400);
    await X.choose('end', 'upToVertex');
    await X.pickBox('endVertex');
    await X.pickFace((g) => g.geomType === 'PLANE' && Math.abs(g.center.z - 20) < 1e-6, [59, 39, 20]);
    const vertex = JSON.stringify(m.state.editing.feature.endVertex);
    m.actions.acceptEditing(); await X.sleep(500);
    const v1 = await X.vol();
    await m.actions.editFeature(f.id); await X.sleep(400);
    await X.choose('end', 'offsetFromSurface');
    await X.pickBox('endFace');
    await X.pickFace((g) => g.geomType === 'PLANE' && Math.abs(g.center.z - 20) < 1e-6);
    m.actions.pmFieldChanged('endOffset', '5', 'length'); await X.sleep(400);
    m.actions.acceptEditing(); await X.sleep(500);
    const v2 = await X.vol();
    // 5 short of the top face: the part outside the block (z −30 … 0) is the same, so the volume too.
    return `${vertex} ${Math.abs(v1 - (48000 + Math.PI * 25 * 30)) < 1e-3} ${Math.abs(v2 - v1) < 1e-3} ${m.active().features.at(-1).end}`;
  })()

(async () => {
    const m = window.__mymechanics; const X = window.__xm;
    const before = await X.vol();
    const s = X.addSketch(X.ref(X.above), (k, S) => { const a = S.addLine(k, 0, 0, 40, 0); S.addLine(k, 40, 0, 40, 20, { from: a.p2 }); });
    await X.extrudeOf(s);
    await X.tick('thin');
    m.actions.pmFieldChanged('thinT1', '2', 'length'); await X.sleep(300);
    m.actions.pmFieldChanged('depth', '10', 'length'); await X.sleep(400);
    const kinds = [...document.querySelectorAll('#left-panel [data-pm-set="thinKind"]')].map((b) => b.dataset.value).join(',');
    m.actions.acceptEditing(); await X.sleep(500);
    const added = Math.round(((await X.vol()) - before) / 10);
    return `${kinds} ${added}`;
  })()

